            {"Super keyword", "super"},
            {"Final keyword", "final"},
            {"User-defined exception", "throw"},
            {"Exception declaration", "throws"},
            {"Exception handling", "try-catch"},
            {"Always-executed block", "finally"},
            {"StringBuffer", "Mutable string"},
